  "claim": {
    "component_id": "C004",
    "value": "Worker-version regressions are a candidate explanation for the export delays.",
    "scope": "A hypothesis, not an established finding.",
    "provenance": {
      "refs": [
        {
          "source_id": "P002",
          "role": "SUPPORT"
