      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans explicitly identify worker-version regressions among the candidate explanations and designate them as hypotheses."
    }
  },
  "signal_basis": {
    "component_id": "C004_signal_basis",
    "value": "Compare evidence across explanations and test sensitivity by worker version and workload. A version association persisting within comparable workloads and execution windows supports a version-related hypothesis; disappearance after accounting for coverage or workload weakens it.",
    "scope": "These are proposed comparative observations, assumed observed for this assessment. Confounding and measurement dependence remain limitations; the comparison does not establish a regression as the cause.",
    "provenance": {
      "refs": [
